import csv
import json

def summarise_file(source, target):
    totals = {}
    rejected = 0
    with open(source, newline="", encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            team = (row.get("team") or "").strip().lower()
            try:
                points = int(row.get("points") or "")
            except ValueError:
                rejected += 1
                continue
            if team == "":
                rejected += 1
                continue
            totals[team] = totals.get(team, 0) + points
    report = {"totals": totals, "rejected": rejected}
    with open(target, "w", encoding="utf-8") as handle:
        json.dump(report, handle, ensure_ascii=False, indent=2)
    return report

print(summarise_file("points.csv", "summary.json"))
